{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "AllowFinanceRole",
      "Effect": "Allow",
      "Principal": {
        "AWS": "arn:aws:iam::123456789012:role/FinanceAppRole"
      },
      "Action": ["s3:PutObject", "s3:GetObject", "s3:ListBucket"],
      "Resource": [
        "arn:aws:s3:::fin-reports-2025",
        "arn:aws:s3:::fin-reports-2025/*"
      ]
    },
    {
      "Sid": "ExplicitDenyPublic",
      "Effect": "Deny",
      "Principal": "*",
      "Action": "s3:GetObject",
      "Resource": "arn:aws:s3:::fin-reports-2025/*",
      "Condition": {
        "StringNotEquals": {
          "aws:PrincipalArn": "arn:aws:iam::123456789012:role/FinanceAppRole"
        }
      }
    },
    {
      "Sid": "DenyUnencryptedUpload",
      "Effect": "Deny",
      "Principal": "*",
      "Action": "s3:PutObject",
      "Resource": "arn:aws:s3:::fin-reports-2025/*",
      "Condition": {
        "StringNotEquals": {
          "s3:x-amz-server-side-encryption": "aws:kms"
        },
        "Null": {
          "s3:x-amz-server-side-encryption": "true"
        }
      }
    }
  ]
}

To enable default encryption: Go to bucket properties, default encryption, select SSE‑S3 (AES‑256). This ensures objects uploaded without explicit encryption headers are still encrypted with SSE‑S3.
